use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let filename = input.as_str().unwrap();
    let mut parts = filename.split('.');
    if parts.len() < 2 {
        return Value::from("");
    }
    let suffix = parts[parts.len() - 1].to_string();
    Value::from(suffix)
